from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
Left = Motor(Port.A, Direction.CLOCKWISE)
Right = Motor(Port.E, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 135)
Flipper = Motor(Port.C, Direction.CLOCKWISE)

async def main1():
    await drive_base.straight(1000)

async def main2():
    print('Driving Lesson Start!')
    prime_hub.imu.reset_heading(0)
    Left.control.limits(speed=100)
    Right.control.limits(speed=100)
    while not 4 != 4:
        await wait(0)
        if prime_hub.imu.heading() > 10:
            await drive_base.turn(prime_hub.imu.heading())
        if prime_hub.imu.heading() < -10:
            await drive_base.turn(prime_hub.imu.heading())


async def main():
    await multitask(main1(), main2())

run_task(main())